#!/usr/bin/env python3
import json, sys
def walk(o, path=""):
    if isinstance(o, dict):
        name = o.get("name") or o.get("test_name")
        res = o.get("status") or o.get("result")
        if name and res:
            print(f"{name:35} {res}")
        for k, v in o.items():
            walk(v, f"{path}/{k}")
    elif isinstance(o, list):
        for v in o:
            walk(v, path)
for f in sys.argv[1:]:
    print("==", f); walk(json.load(open(f)))
EOF
